/* Structured mock practice, with an honest self-review instead of invented AI scores. */
const mockKey="dv-mock.v1",mockHistoryKey="dv-mock-history.v1";
let mockScenarios=[],mockFilter="All",mockState=null;
try{const saved=JSON.parse(localStorage.getItem(mockKey)||"null");if(saved&&typeof saved.id==="string"&&Number.isFinite(saved.startedAt)&&["answer","review"].includes(saved.phase)&&saved.responses&&typeof saved.responses==="object")mockState=saved}catch(e){}
const mockSave=()=>{try{if(mockState)localStorage.setItem(mockKey,JSON.stringify(mockState));else localStorage.removeItem(mockKey)}catch(e){}};
const mockHistory=()=>{try{const rows=JSON.parse(localStorage.getItem(mockHistoryKey)||"[]");return Array.isArray(rows)?rows.filter(row=>row&&typeof row.id==="string"&&Number.isFinite(row.finishedAt)).slice(0,20):[]}catch(e){return[]}};
const mockClock=ms=>`${String(Math.floor(ms/60_000)).padStart(2,"0")}:${String(Math.floor(ms%60_000/1000)).padStart(2,"0")}`;
async function loadMockScenarios(){try{const response=await fetch("mock-scenarios.json");if(!response.ok)throw new Error("Could not load mocks");const items=await response.json();if(!Array.isArray(items)||!items.length)throw new Error("Invalid mock scenarios");mockScenarios=items;if(location.hash==="#mock")renderMock()}catch(e){const root=document.getElementById("mock-root");if(root&&location.hash==="#mock")root.textContent="Mock practice could not load. Refresh and try again."}}
function startMock(id){const scenario=mockScenarios.find(item=>item.id===id);if(!scenario)return;mockState={id,startedAt:Date.now(),phase:"answer",responses:{clarify:"",answer:"",tradeoffs:""},checks:[]};mockSave();renderMock()}
function saveMockReview(){if(!mockState||mockState.phase!=="review")return;const history=mockHistory();history.unshift({...mockState,finishedAt:Date.now()});try{localStorage.setItem(mockHistoryKey,JSON.stringify(history.slice(0,20)))}catch(e){}mockState=null;mockSave();renderMock()}
function renderMock(){const root=document.getElementById("mock-root");if(!root)return;if(!mockScenarios.length){root.innerHTML='<p class="why">Loading mock practice…</p>';return}
  if(mockState){const state=mockState,scenario=mockScenarios.find(item=>item.id===state.id);if(!scenario){mockState=null;mockSave();renderMock();return}
    const remaining=Math.max(0,state.startedAt+scenario.minutes*60_000-Date.now());if(!remaining&&state.phase==="answer"){state.phase="review";mockSave()}
    const review=state.phase==="review";
    root.innerHTML=`<div class="mk-head"><div><span class="mono">${esc(scenario.type)} · ${scenario.minutes} minute mock</span><h3>${esc(scenario.title)}</h3></div><strong id="mk-timer" class="${remaining<300_000?"warn":""}" role="timer">${review?"Review":mockClock(remaining)}</strong></div><div class="mk-layout"><section class="ip-card"><h4>Prompt</h4><p>${esc(scenario.prompt)}</p><h4>Questions to clarify</h4><ul>${scenario.clarify.map(item=>`<li>${esc(item)}</li>`).join("")}</ul>${review?`<div class="mk-response"><h4>Your notes</h4>${["clarify","answer","tradeoffs"].map(field=>`<p><b>${{clarify:"Clarifications",answer:"Answer",tradeoffs:"Tradeoffs and follow-ups"}[field]}:</b> ${esc(state.responses[field]||"No notes saved")}</p>`).join("")}</div>`:`<div class="mk-fields"><label for="mk-clarify">Clarifying questions and assumptions</label><textarea id="mk-clarify" placeholder="What would you ask before proposing a solution?"></textarea><label for="mk-answer">${scenario.type==="Behavioral"?"Your story":"Architecture and data flow"}</label><textarea id="mk-answer" class="mk-main-answer" placeholder="Work through your answer here…"></textarea><label for="mk-tradeoffs">Tradeoffs, risks, and follow-ups</label><textarea id="mk-tradeoffs" placeholder="What might fail or need a different choice at scale?"></textarea></div>`}</section><aside class="ip-card mk-side">${review?`<h4>Self-review</h4><p>Check only what your answer actually covered. This score is your own assessment.</p><div class="mk-checks">${scenario.rubric.map((item,index)=>`<label><input type="checkbox" data-check="${index}" ${state.checks?.includes(index)?"checked":""}><span>${esc(item)}</span></label>`).join("")}</div><p class="mk-score">${state.checks?.length||0} of ${scenario.rubric.length} criteria checked</p><button class="btn" id="mk-save">Save review</button>`:`<h4>Interview habits</h4><p>Ask clarifying questions first. Explain your choices aloud. State what could break and how you would test it.</p><p>Drafts are saved in this browser as you type.</p><button class="btn" id="mk-finish">Finish and review</button>`}<button class="btn off" id="mk-exit">End without saving</button></aside></div>`;
    if(!review)for(const field of ("clarify","answer","tradeoffs"))document.getElementById("mk-"+field).value=state.responses[field]||"";
    return
  }
  const history=mockHistory(),visible=mockScenarios.filter(item=>mockFilter==="All"||item.type===mockFilter);
  root.innerHTML=`<div class="mk-tabs" role="group" aria-label="Mock type">${["All","System design","Behavioral"].map(type=>`<button class="${mockFilter===type?"on":""}" data-filter="${type}" aria-pressed="${mockFilter===type}">${type}</button>`).join("")}</div>${history.length?`<div class="ip-card mk-history"><h3>Recent reviews</h3>${history.slice(0,5).map(row=>{const item=mockScenarios.find(s=>s.id===row.id);return `<div><span>${esc(item?.title||row.id)} <small>· ${new Date(row.finishedAt).toLocaleDateString()}</small></span><b>${row.checks?.length||0}/${item?.rubric.length||4}</b><button data-start="${esc(row.id)}">Try again</button></div>`}).join("")}</div>`:""}<div class="mk-grid">${visible.map(item=>`<article class="ip-card mk-card"><span class="mono">${esc(item.type)} · ${item.minutes} min</span><h3>${esc(item.title)}</h3><p>${esc(item.prompt)}</p><button class="btn off" data-start="${item.id}">Start mock</button></article>`).join("")}</div><p class="rp-note">These are original practice prompts. Reviews are self-assessments; no interviewer or AI has graded them.</p>`
}
document.getElementById("mock-root").addEventListener("input",event=>{if(!mockState||mockState.phase!=="answer")return;const field=event.target.id?.slice(3);if(!["clarify","answer","tradeoffs"].includes(field))return;mockState.responses[field]=event.target.value;mockSave()});
document.getElementById("mock-root").addEventListener("change",event=>{if(!mockState||mockState.phase!=="review"||event.target.dataset.check===undefined)return;const index=Number(event.target.dataset.check);mockState.checks=mockState.checks||[];mockState.checks=event.target.checked?[...new Set([...mockState.checks,index])]:mockState.checks.filter(value=>value!==index);mockSave();document.querySelector(".mk-score").textContent=`${mockState.checks.length} of ${mockScenarios.find(item=>item.id===mockState.id).rubric.length} criteria checked`});
document.getElementById("mock-root").addEventListener("click",event=>{const target=event.target.closest("button");if(!target)return;if(target.dataset.filter){mockFilter=target.dataset.filter;renderMock();return}if(target.dataset.start){startMock(target.dataset.start);return}if(target.id==="mk-finish"&&mockState){mockState.phase="review";mockSave();renderMock();return}if(target.id==="mk-save"){saveMockReview();return}if(target.id==="mk-exit"){mockState=null;mockSave();renderMock()}});
setInterval(()=>{if(location.hash!=="#mock"||!mockState||mockState.phase!=="answer")return;const scenario=mockScenarios.find(item=>item.id===mockState.id);if(!scenario)return;const remaining=Math.max(0,mockState.startedAt+scenario.minutes*60_000-Date.now());const timer=document.getElementById("mk-timer");if(timer){timer.textContent=mockClock(remaining);timer.classList.toggle("warn",remaining<300_000)}if(!remaining){mockState.phase="review";mockSave();renderMock()}},1000);
